import{z as A,x as B,o as r,c as m,q as l,j as o,D as e,d as E,s as n,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"ArF 准分子激光器","description":"","frontmatter":{"title":"ArF 准分子激光器","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/arf-excimer-laser.md","filePath":"litho/arf-excimer-laser.md","lastUpdated":1791413859000}'),d={name:"litho/arf-excimer-laser.md"};function h(p,a,D,c,F,f){const i=B("Mermaid");return r(),m("div",null,[a[2]||(a[2]=l('<h1 id="arf-准分子激光器" tabindex="-1">ArF 准分子激光器 <a class="header-anchor" href="#arf-准分子激光器" aria-label="Permalink to &quot;ArF 准分子激光器&quot;">​</a></h1><div class="epigraph"><p>193 nm 量产光来自 ArF 准分子放电，不是汞灯的 i 线尾巴。脉冲、气体和腔镜是剂量与带宽的上游。</p><footer>—— 对照 Cymer / Gigaphoton 公开的 ArF 准分子光源；波长台阶见 [litho-wavelengths](/litho/litho-wavelengths)</footer></div><p><a href="/litho/complementary-euv">上一课</a>收在互补式 EUV：几何仍是 1D+cut，切孔的剂量与随机往往比长直线更苛刻。DUV 主干与胶、轨道补层到此；缺口转到<strong>曝光机里面谁发光</strong>。本课是「曝光机子系统」第一课：ArF 准分子激光器。不重推 <a href="/litho/rayleigh-litho">瑞利判据</a>，也不把浸没水膜再讲一遍——<a href="/litho/arf-immersion">ArF 浸没</a> 假定光源已经是 193 nm。后课带宽、脉冲能量、气体寿命都默认本课的放电结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干把 193 nm 写成波长台阶上的一个点。机台里它是稀有气体卤化物放电：氩与氟在高压脉冲下形成 ArF*，退激发出约 193.3 nm。汞灯连续谱滤不出这条线的亮度与窄带；准分子是脉冲、高峰值、可压窄的。缺口是把「193 nm」落到腔、放电和为什么后课要谈线宽。</p><p><span class="marginnote">术语翻译：准分子（excimer）= excited dimer，『激发态的二聚体』——只存在于激发态的短命分子。ArF* 里的星号就代表激发态；它退激发时把能量以约 193 nm 的光子吐出来。</span></p><p><span class="marginnote">KrF 248 nm 是另一台准分子（KrF*），不是把 ArF 换滤光片。气体、镀膜、光路材料整套换。本课只钉 ArF 浸没量产这一条。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>振荡级加放大级（MOPA 或同类主振–功放）是公开架构：振荡级出窄带种子，放大级出功率。光束再进照明均光。剂量按脉冲计数 × 单脉冲能量；重复频率进 <a href="/litho/scanner-throughput">扫描仪产能</a>。本课不写具体 kHz 广告值当物理常数。</p><p><span class="marginnote">把『剂量按脉冲计数』换成具体数：若单脉冲在像面贡献 10 mJ/cm²、胶要 30 mJ/cm²，同一处就要叠约 3 个脉冲；重复频率与扫描速度若失配，同一处多收一个脉冲，CD 立刻偏一截。</span></p>',10)),(r(),o(s,null,{default:e(()=>[n(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIS%5B%22ArF%20%E6%94%BE%E7%94%B5%22%5D%20--%3E%20SEED%5B%22%E7%AA%84%E5%B8%A6%E6%8C%AF%E8%8D%A1%22%5D%0A%20%20SEED%20--%3E%20AMP%5B%22%E6%94%BE%E5%A4%A7%22%5D%0A%20%20AMP%20--%3E%20ILL%5B%22%E7%85%A7%E6%98%8E%20%2F%20%E5%9D%87%E5%85%89%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"准分子寿命短，不能当连续波腔慢慢建场，必须脉冲放电。光谱天然比需要的成像带宽宽，所以下一课必须压窄，否则色差与焦深被吃掉。氟腐蚀光学件，气体寿命是运行成本，再后一课。",-1)),(r(),o(s,null,{default:e(()=>[n(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20EX%5B%22ArF*%20%E5%AF%BF%E5%91%BD%20%E7%BA%B3%E7%A7%92%E7%BA%A7%22%5D%20--%3E%20PULSE%5B%22%E5%8F%AA%E8%83%BD%E8%84%89%E5%86%B2%E6%94%BE%E7%94%B5%20%E4%B8%8D%E8%83%BD%E8%BF%9E%E7%BB%AD%E5%BB%BA%E5%9C%BA%22%5D%0A%20%20PULSE%20--%3E%20CNT%5B%22%E5%89%82%E9%87%8F%20%3D%20%E8%84%89%E5%86%B2%E6%95%B0%20%C3%97%20%E5%8D%95%E8%84%89%E5%86%B2%E8%83%BD%E9%87%8F%22%5D%0A%20%20CNT%20--%3E%20SYNC%5B%22%E9%87%8D%E5%A4%8D%E9%A2%91%E7%8E%87%E4%B8%8E%E6%89%AB%E6%8F%8F%E5%90%8C%E6%AD%A5%22%5D%0A%20%20SYNC%20--%3E%20DRIFT%5B%22%E8%83%BD%E9%87%8F%E6%BC%82%E7%A7%BB%20%E2%86%92%20CD%20%E6%BC%82%20%E2%86%92%20%E8%83%BD%E9%87%8F%E5%8F%8D%E9%A6%88%22%5D%0A%20%20PULSE%20--%3E%20BW%5B%22%E5%85%89%E8%B0%B1%E5%A4%A9%E7%84%B6%E5%81%8F%E5%AE%BD%20%E2%86%92%20%E4%B8%8B%E4%B8%80%E8%AF%BE%E5%8E%8B%E7%AA%84%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">常见误区：把激光器当『通电就亮的灯』。ArF* 寿命只有纳秒量级，来不及在腔里慢慢建连续振荡，只能每放电打一发脉冲——脉冲性是分子寿命逼出来的物理，不是工程偏好。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 EUV 锡滴 LPP——那是另一条波长的光源课。下一课只谈线宽压窄，不改放电化学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>193 nm 量产光是 ArF 准分子脉冲，不是灯。</li><li>功率与光谱分属放大与压窄，后课拆开。</li><li>出处：准分子光源公开架构；波长台阶课。</li></ul>',5))])}const P=A(d,[["render",h]]);export{_ as __pageData,P as default};
